// Search defaults live here. The API applies
// max_entries independently to MPs and funders, then merges by similarity.
export const searchConfiguration = {
  minimumCharacters: 3,
  debounceMs: 250,
  maxEntriesPerType: 10,
  strictness: 1,
  timeoutMs: 10_000,
};

export function readStrictness(value: string | null): number {
  if (!value?.trim()) return searchConfiguration.strictness;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1
    ? Math.round(parsed * 100) / 100
    : searchConfiguration.strictness;
}

export interface Entity {
  name: string;
  kind: "MP" | "Funder";
  funderKind: string | null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readEntities(body: unknown): Entity[] {
  if (!isRecord(body) || !Array.isArray(body.entities)) {
    throw new Error("Search returned an unexpected response. Try again.");
  }

  return body.entities.map((value: unknown) => {
    if (
      !isRecord(value) ||
      typeof value.name !== "string" ||
      (value.kind !== "MP" && value.kind !== "Funder") ||
      (value.funder_kind !== null && typeof value.funder_kind !== "string")
    ) {
      throw new Error("Search returned an unexpected response. Try again.");
    }
    return {
      name: value.name,
      kind: value.kind,
      funderKind: value.funder_kind,
    };
  });
}

export async function searchEntities(
  term: string,
  signal: AbortSignal,
  strictness: number,
): Promise<Entity[]> {
  const controller = new AbortController();
  let timedOut = false;
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  const timeout = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, searchConfiguration.timeoutMs);

  try {
    const params = new URLSearchParams({
      term,
      max_entries: String(searchConfiguration.maxEntriesPerType),
      strictness: String(strictness),
    });
    const response = await fetch(`/api/search?${params}`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(
        "The search service is unavailable. Try again in a moment.",
      );
    }
    const body: unknown = await response.json();
    return readEntities(body);
  } catch (error) {
    if (timedOut) throw new Error("Search is taking too long. Try again.");
    if (signal.aborted) throw error;
    if (error instanceof TypeError || error instanceof SyntaxError) {
      throw new Error(
        "Couldn’t connect to search. Check your connection and try again.",
      );
    }
    throw error;
  } finally {
    clearTimeout(timeout);
    signal.removeEventListener("abort", cancel);
  }
}

export function entityType(entity: Entity): string {
  if (entity.kind === "MP") return "MP";
  return `Funder: ${funderKindLabel(entity.funderKind)}`;
}

export function funderKindLabel(value: string | null): string {
  const kind = value?.trim();
  if (!kind || kind.toLowerCase() === "not specified") return "Unclassified";
  if (kind.toLowerCase() === "individual") return "Individual";
  if (kind.toLowerCase() === "company") return "Company";
  if (kind.toLowerCase() === "trade union") return "Trade union";
  return kind;
}

export function funderKindIcon(value: string | null) {
  switch (funderKindLabel(value).toLowerCase()) {
    case "individual":
      return "person";
    case "company":
      return "building";
    case "trade union":
      return "group";
    case "unclassified":
      return "question";
    default:
      return "tag";
  }
}

// Plain-text segments keep source names intact and never interpret names or
// user input as markup. Matching here only highlights; it never changes rank.
export function highlightName(name: string, term: string) {
  const tokens = [...new Set(term.trim().split(/\s+/u).filter(Boolean))]
    .sort((a, b) => b.length - a.length)
    .map((token) => token.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  if (!tokens.length) return [{ text: name, matched: false }];
  const pattern = new RegExp(tokens.join("|"), "giu");
  const segments: { text: string; matched: boolean }[] = [];
  let position = 0;
  for (const match of name.matchAll(pattern)) {
    const start = match.index;
    if (start > position)
      segments.push({ text: name.slice(position, start), matched: false });
    segments.push({ text: match[0], matched: true });
    position = start + match[0].length;
  }
  if (position < name.length)
    segments.push({ text: name.slice(position), matched: false });
  return segments;
}
<script lang="ts">
  import Icon from "./lib/Icon.svelte";
  import EntityIndicator from "./lib/EntityIndicator.svelte";
  import {
    highlightName,
    readStrictness,
    searchConfiguration,
    searchEntities,
    type Entity,
  } from "./lib/search";

  type SearchState =
    | { status: "idle" }
    | { status: "loading"; term: string }
    | { status: "success"; term: string; entities: Entity[] }
    | { status: "error"; term: string; message: string };

  let query = $state(new URL(window.location.href).searchParams.get("q") ?? "");
  let strictness = $state(
    readStrictness(
      new URL(window.location.href).searchParams.get("strictness"),
    ),
  );
  let composing = $state(false);
  let attempt = $state(0);
  let input: HTMLInputElement;
  let searchState = $state<SearchState>({ status: "idle" });
  const term = $derived(query.trim());
  const charactersNeeded = $derived(
    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
  );
  const announcement = $derived(
    searchState.status === "loading"
      ? "Searching…"
      : searchState.status === "success"
        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
        : "",
  );

  $effect(() => {
    const currentTerm = term;
    const currentStrictness = strictness;
    const currentAttempt = attempt;
    if (
      composing ||
      [...currentTerm].length < searchConfiguration.minimumCharacters
    ) {
      searchState = { status: "idle" };
      return;
    }

    const controller = new AbortController();
    let current = true;
    searchState = { status: "loading", term: currentTerm };
    const timer = setTimeout(
      async () => {
        try {
          const entities = await searchEntities(
            currentTerm,
            controller.signal,
            currentStrictness,
          );
          if (current)
            searchState = { status: "success", term: currentTerm, entities };
        } catch (error) {
          if (current)
            searchState = {
              status: "error",
              term: currentTerm,
              message:
                error instanceof Error
                  ? error.message
                  : "Search couldn’t load. Try again.",
            };
        }
      },
      currentAttempt > 0 ? 0 : searchConfiguration.debounceMs,
    );

    return () => {
      current = false;
      clearTimeout(timer);
      controller.abort();
    };
  });

  function updateQuery(value: string) {
    attempt = 0;
    query = value;
    const url = new URL(window.location.href);
    if (value.trim()) url.searchParams.set("q", value.trim());
    else url.searchParams.delete("q");
    window.history.replaceState(null, "", url);
  }

  function updateStrictness(value: string) {
    attempt = 0;
    strictness = readStrictness(value);
    const url = new URL(window.location.href);
    url.searchParams.set("strictness", String(strictness));
    window.history.replaceState(null, "", url);
  }

  function clearSearch() {
    updateQuery("");
    input.focus();
  }

  function shortcut(event: KeyboardEvent) {
    const target = event.target;
    const editing =
      target instanceof HTMLElement &&
      (target.isContentEditable ||
        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
    if (
      event.key === "/" &&
      !editing &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      event.preventDefault();
      input.focus();
    }
    if (event.key === "Escape" && target === input && !event.isComposing)
      clearSearch();
  }

  function atLimit(entities: Entity[]) {
    return ["MP", "Funder"].some(
      (kind) =>
        entities.filter((entity) => entity.kind === kind).length >=
        searchConfiguration.maxEntriesPerType,
    );
  }
</script>

