        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&Funder::new("heavenly ltd".into(), FunderKind::Company),)
        );
        assert_eq!(
            ranked.get(2).unwrap(),
            &Entity::from(&ParliamentMember::new(
                "hades".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(3).unwrap(),
            &Entity::from(&Funder::new("canna ltd".into(), FunderKind::Company),)
        );
    }

    #[test]
    fn works_for_more_funders() {
        let funders = vec![
            (
                Funder::new("heavenly ltd".into(), FunderKind::Company),
                SearchSimilarity::from(4_f32),
            ),
            (
                Funder::new("canna ltd".into(), FunderKind::Company),
                SearchSimilarity::from(2_f32),
            ),
        ];
        let mps = vec![(
            ParliamentMember::new("johnny larner".into(), 1, String::new(), 1, String::new()),
            SearchSimilarity::from(4_f32),
        )];

        let ranked = merge_scores(&mps, &funders);
        assert_eq!(ranked.len(), 3);
        assert_eq!(
            ranked.first().unwrap(),
            &Entity::from(&ParliamentMember::new(
                "johnny larner".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&Funder::new("heavenly ltd".into(), FunderKind::Company),)
        );
        assert_eq!(
            ranked.get(2).unwrap(),
            &Entity::from(&Funder::new("canna ltd".into(), FunderKind::Company),)
        );
    }

    #[test]
    fn works_for_more_mps() {
        let funders = vec![(
            Funder::new("canna ltd".into(), FunderKind::Company),
            SearchSimilarity::from(2_f32),
        )];
        let mps = vec![
            (
                ParliamentMember::new("johnny larner".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(4_f32),
            ),
            (
                ParliamentMember::new("hades".into(), 1, String::new(), 1, String::new()),
                SearchSimilarity::from(2_f32),
            ),
        ];

        let ranked = merge_scores(&mps, &funders);
        assert_eq!(
            ranked.first().unwrap(),
            &Entity::from(&ParliamentMember::new(
                "johnny larner".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(1).unwrap(),
            &Entity::from(&ParliamentMember::new(
                "hades".into(),
                1,
                String::new(),
                1,
                String::new(),
            ))
        );
        assert_eq!(
            ranked.get(2).unwrap(),
            &Entity::from(&Funder::new("canna ltd".into(), FunderKind::Company,))
        );
    }
